public class SingletonExam {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

	
	int x = 1;
	int y= 3;
	
int result = x++ + ++y;
System.out.println( "x: " + x);
System.out.println( "y: " + y);
System.out.println( "result: " + result);


	
	
	
	
	}

}
